// Code prices the order. The AI only read the message.
const { stock, zones } = $('Read stock and zones').first().json;
const ai = $input.first().json.output || $input.first().json || {};
const norm = s => String(s || '').toLowerCase().trim();
const lines = [], problems = [...(ai.unclear || [])];
for (const it of (ai.items || [])) {
  const s = stock.find(p => norm(p.name) === norm(it.product) || (p.aliases || []).map(norm).includes(norm(it.product)));
  const q = Math.floor(Number(it.quantity));
  if (!s) { problems.push(`"${it.product}" isn't on our list`); continue; }
  if (!(q > 0)) { problems.push(`how many ${s.unit}s of ${s.name}?`); continue; }
  if (q > s.qty) { problems.push(`only ${s.qty} ${s.unit}s of ${s.name} left today`); continue; }
  const prev = lines.find(l => l.sku === s.sku);
  if (prev) { prev.quantity += q; prev.line_ngn = prev.quantity * prev.price_ngn; }
  else lines.push({ sku: s.sku, name: s.name, unit: s.unit, quantity: q, price_ngn: s.price_ngn, line_ngn: q * s.price_ngn });
}
const zone = (zones || []).find(z => norm(z.zone) === norm(ai.delivery_area));
if (!zone) problems.push(ai.delivery_area ? `we don't deliver to ${ai.delivery_area} yet` : 'which area should we deliver to?');
if (!lines.length && !problems.length) problems.push('which products would you like?');
const goods = lines.reduce((a, l) => a + l.line_ngn, 0);
const fee = zone ? zone.fee_ngn : 0;
const c = $('From HL·01').first().json;
return [{ json: {
  wa_id: c.wa_id, phone: c.phone, name: c.name,
  items: lines, zone: zone ? zone.zone : null, delivery_ngn: fee,
  total_ngn: goods + fee, problems, ok: problems.length === 0
} }];

